import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"April 2019 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"April 2019 :: Ceph Developer Monthly","date":"2019-04-09T00:00:00.000Z","updated":"2019-04-09T00:00:00.000Z","tags":["Ceph","分布式存储","监控内存目标","Orchestrator","遥测"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/April_2019_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/April_2019_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),o={name:"posts/2019/April_2019_-_-_Ceph_Developer_Monthly.md"};function s(p,l,a,n,_,h){return e(),t("div",null,[...l[0]||(l[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2019年4月（具体日期未提及）</p><p><strong>参会人员</strong>：</p><ul><li>Adam（负责内存目标选项）</li><li>Shirred（负责内存目标选项）</li><li>Val（负责监控内存目标）</li><li>Mocha（负责蓝店内存管理）</li><li>Steve（负责OSD缓存）</li><li>Sebastian（负责Orchestrator）</li><li>Patrick（负责Orchestrator）</li><li>Dan（负责监控内存目标）</li><li>Jason（负责RBD MBD）</li><li>Neha（负责Octopus）</li><li>Mike（负责RBD MBD）</li><li>其他相关人员</li></ul><p><strong>会议主题</strong>：</p><ol><li><p><strong>监控内存目标</strong>：</p><ul><li>讨论了为监控设置内存目标选项的需求，类似于USD中的内存目标选项。</li><li>讨论了在蓝店中实现内存目标选项的方法，并考虑将其复制到监控中。</li><li>讨论了使用优先级缓存接口来管理不同内存缓存的需求。</li><li>决定由Shirred负责实现内存目标选项，并更新配置选项。</li></ul></li><li><p><strong>Orchestrator</strong>：</p><ul><li>讨论了不同Orchestrator的实现现状，包括Ansible、Baroque、Kubernetes和DeepSea。</li><li>讨论了在Barcelona Ceph会议上讨论Orchestrator路线图的计划。</li><li>讨论了DeepSea和SSH Orchestrator的未来方向。</li><li>讨论了使用SSH Orchestrator进行初始化部署的方案。</li></ul></li><li><p><strong>遥测</strong>：</p><ul><li>讨论了遥测模块的功能和用途。</li><li>讨论了从遥测数据中生成有用报告的需求，例如集群大小分布、安装版本分布和崩溃报告。</li><li>讨论了使用Qivana和Kibana等工具进行数据分析和可视化。</li><li>决定由End开发有用的报告，并考虑使用Qivana进行交互式查询。</li></ul></li><li><p><strong>RBD MBD</strong>：</p><ul><li>讨论了RBD MBD在Kubernetes环境中的集成和优化。</li><li>讨论了使用RBD MBD CLI进行操作的需求。</li><li>讨论了在单个RBD MBD守护进程中支持多个RBD连接的需求。</li><li>讨论了使用网络接口动态添加和删除块设备的需求。</li><li>决定由Mike负责改进RBD MBD与Kubernetes的集成。</li></ul></li><li><p><strong>Octopus</strong>：</p><ul><li>讨论了Octopus的待办事项列表，包括在线响应、内存优化、克隆、恢复和审计。</li><li>讨论了将部分恢复和易于恢复的功能合并到Octopus的需求。</li><li>讨论了优先级恢复和自适应恢复的需求。</li><li>讨论了将Toshiba的RocksDB Roadmap集成到Ceph的需求。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>Shirred实现内存目标选项并更新配置选项。</li><li>Sebastian和Patrick整理Orchestrator路线图，并在Barcelona Ceph会议上讨论。</li><li>End开发有用的遥测报告。</li><li>Mike改进RBD MBD与Kubernetes的集成。</li><li>Neha和团队完成Octopus的待办事项列表。</li><li>Adam和团队评估Toshiba的RocksDB Roadmap，并考虑集成。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph社区的贡献和代码审查流程。</li><li>讨论了Ceph项目的长期发展方向。</li></ul>",10)])])}const D=i(o,[["render",s]]);export{u as __pageData,D as default};
